'use strict';

import utils from '../utils.js';
import AxiosError from '../core/AxiosError.js';
import platform from '../platform/index.js';
import {VERSION} from '../env/data.js';
import PlatformFormData from '../platform/node/classes/FormData.js';
import {getProxyForUrl} from 'proxy-from-env';

/**
 * Determines whether the specified URL is absolute
 *
 * @param {string} url The URL to test
 *
 * @returns {boolean} True if the specified URL is absolute, otherwise false
 */
export default function isAbsoluteURL(url) {
  // A URL is considered absolute if it begins with "<scheme>://" or "//" (protocol-relative URL).
  // RFC 3986 defines scheme name as a sequence of characters beginning with a letter and followed
  // by any combination of letters, digits, plus, period, or hyphen.
  return /^([a-z][a-z\d+\-.]*:)?\/\//i.test(url);
}

class AxiosURLResolver {
  constructor() {
    this.urlPolicy = {
      rejectNull: false,
      emptyURL: '',
      pathSeparator: '/',
      protocolRelativePrefix: '//',
      fallbackBase: 'http://localhost',
      dataProtocol: 'data:',
      dataProtocolName: 'data',
      supportedProtocols: platform.protocols.map(protocol => protocol + ':'),
      httpsPattern: /https:?/,
      dataURIPattern: /^(?:([^;]+);)?(?:[^;]+;)?(base64|),([\s\S]*)$/,
      protocolPattern: /^([-+\w]{1,25})(:?\/\/|:)/,
      trailingSlashPattern: /\/?\/$/,
      leadingSlashPattern: /^\/+/,
      hasStandardBrowserEnv: !!platform.hasStandardBrowserEnv,
      hasBrowserEnv: !!platform.hasBrowserEnv,
      msie: false,
      urlParsingNode: null,
      originURL: null
    };

    this.queryPolicy = {
      hashMark: '#',
      queryDelimiter: '?',
      pairDelimiter: '&',
      encodeReplacements: [
        [/%3A/gi, ':'],
        [/%24/g, '$'],
        [/%2C/gi, ','],
        [/%20/g, '+'],
        [/%5B/gi, '['],
        [/%5D/gi, ']']
      ],
      metaTokens: true,
      dots: false,
      indexes: false,
      formKeyPattern: /\w+|\[(\w*)]/g,
      predicates: utils.toFlatObject(utils, {}, null, function filter(prop) {
        return /^is[A-Z]/.test(prop);
      })
    };

    this.headerPolicy = {
      ignoreDuplicateOf: utils.toObjectSet([
        'age', 'authorization', 'content-length', 'content-type', 'etag',
        'expires', 'from', 'host', 'if-modified-since', 'if-unmodified-since',
        'last-modified', 'location', 'max-forwards', 'proxy-authorization',
        'referer', 'retry-after', 'user-agent'
      ]),
      hasStandardBrowserEnv: !!platform.hasStandardBrowserEnv,
      hasStandardBrowserWebWorkerEnv: !!platform.hasStandardBrowserWebWorkerEnv,
      hasBrowserEnv: !!platform.hasBrowserEnv,
      xsrfCookieName: 'XSRF-TOKEN',
      xsrfHeaderName: 'X-XSRF-TOKEN',
      userAgent: 'axios/' + VERSION,
      headerNamePattern: /^[-_a-zA-Z0-9^`|~,!#$%&'*+.]+$/,
      tokenPattern: /([^\s,;=]+)\s*(?:=\s*([^,;]+))?/g,
      cookieSplitPatternPrefix: '(^|;\\s*)(',
      cookieSplitPatternSuffix: ')=([^;]*)',
      basicPrefix: 'Basic ',
      proxyAuthPrefix: 'Basic ',
      acceptEncoding: 'gzip, compress, deflate',
      brotliToken: ', br'
    };

    this.configPolicy = {
      emptyConfig: {},
      defaultCaseless: undefined,
      defaultMethod: 'get',
      allowUnknownOptions: false,
      version: VERSION,
      mergeStyle: 'config',
      proxyAuthSeparator: ':',
      addressFamilyDot: '.',
      ipv4: 4,
      ipv6: 6,
      deprecatedWarnings: {}
    };

    this.validators = this.createValidators();
    this.deprecatedWarnings = this.configPolicy.deprecatedWarnings;

    if (this.urlPolicy.hasStandardBrowserEnv && typeof document !== 'undefined' && typeof navigator !== 'undefined') {
      this.urlPolicy.msie = /(msie|trident)/i.test(navigator.userAgent);
      this.urlPolicy.urlParsingNode = document.createElement('a');
      this.urlPolicy.originURL = this.resolveBrowserURL(window.location.href);
    }
  }

  isAbsolute(url) {
    const policy = this.urlPolicy;
    if (url == null && policy.rejectNull) {
      return false;
    }
    return isAbsoluteURL(url);
  }

  isProtocolRelative(url) {
    const prefix = this.urlPolicy.protocolRelativePrefix;
    if (typeof url !== 'string') {
      return false;
    }
    return url.indexOf(prefix) === 0;
  }

  stripTrailingSlashes(url) {
    const policy = this.urlPolicy;
    if (!url) {
      return policy.emptyURL;
    }
    return String(url).replace(policy.trailingSlashPattern, '');
  }

  stripLeadingSlashes(url) {
    const policy = this.urlPolicy;
    if (!url) {
      return policy.emptyURL;
    }
    return String(url).replace(policy.leadingSlashPattern, '');
  }

  joinURLPath(baseURL, relativeURL) {
    const separator = this.urlPolicy.pathSeparator;
    if (!relativeURL) {
      return baseURL;
    }
    return this.stripTrailingSlashes(baseURL) + separator + this.stripLeadingSlashes(relativeURL);
  }

  combine(baseURL, relativeURL) {
    const policy = this.urlPolicy;
    return relativeURL
      ? baseURL.replace(policy.trailingSlashPattern, '') + policy.pathSeparator + relativeURL.replace(policy.leadingSlashPattern, '')
      : baseURL;
  }

  buildFullPath(baseURL, requestedURL) {
    const policy = this.urlPolicy;
    if (baseURL && !this.isAbsolute(requestedURL)) {
      return this.combine(baseURL, requestedURL);
    }
    if (requestedURL == null && policy.rejectNull) {
      return policy.emptyURL;
    }
    return requestedURL;
  }

  parseProtocol(url) {
    const policy = this.urlPolicy;
    const match = policy.protocolPattern.exec(url);
    return match && match[1] || policy.emptyURL;
  }

  hasSupportedProtocol(protocol) {
    const policy = this.urlPolicy;
    if (!protocol) {
      return false;
    }
    const normalized = protocol.endsWith(':') ? protocol : protocol + ':';
    return policy.supportedProtocols.indexOf(normalized) !== -1;
  }

  isHttpsProtocol(protocol) {
    const policy = this.urlPolicy;
    if (!protocol) {
      return false;
    }
    return policy.httpsPattern.test(protocol);
  }

  parseAdapterURL(config) {
    const policy = this.urlPolicy;
    const fullPath = this.buildFullPath(config.baseURL, config.url);
    const parsed = new URL(fullPath, policy.fallbackBase);
    const protocol = parsed.protocol || policy.supportedProtocols[0];
    return {
      fullPath,
      parsed,
      protocol
    };
  }

  extractURLAuth(parsed) {
    const policy = this.urlPolicy;
    if (!parsed) {
      return policy.emptyURL;
    }
    if (!parsed.username && !parsed.password) {
      return null;
    }
    const username = parsed.username || policy.emptyURL;
    const password = parsed.password || policy.emptyURL;
    return username + ':' + password;
  }

  composeOrigin(protocol, parsed) {
    const policy = this.urlPolicy;
    if (!parsed) {
      return policy.emptyURL;
    }
    const hostname = parsed.hostname || policy.emptyURL;
    const port = parsed.port ? ':' + parsed.port : policy.emptyURL;
    const path = parsed.path || policy.emptyURL;
    return protocol + '//' + hostname + port + path;
  }

  matchDataURI(uri) {
    const policy = this.urlPolicy;
    if (!uri) {
      return null;
    }
    return policy.dataURIPattern.exec(uri);
  }

  decodeDataURI(uri, asBlob, options) {
    const policy = this.urlPolicy;
    const _Blob = options && options.Blob || platform.classes.Blob;
    const protocol = this.parseProtocol(uri);

    if (asBlob === undefined && _Blob) {
      asBlob = true;
    }

    if (protocol === policy.dataProtocolName) {
      uri = protocol.length ? uri.slice(protocol.length + 1) : uri;
      const match = this.matchDataURI(uri);

      if (!match) {
        throw new AxiosError('Invalid URL', AxiosError.ERR_INVALID_URL);
      }

      const mime = match[1];
      const isBase64 = match[2];
      const body = match[3];
      const buffer = Buffer.from(decodeURIComponent(body), isBase64 ? 'base64' : 'utf8');

      if (asBlob) {
        if (!_Blob) {
          throw new AxiosError('Blob is not supported', AxiosError.ERR_NOT_SUPPORT);
        }
        return new _Blob([buffer], {type: mime});
      }

      return buffer;
    }

    throw new AxiosError('Unsupported protocol ' + protocol, AxiosError.ERR_NOT_SUPPORT);
  }

  resolveBrowserURL(url) {
    const policy = this.urlPolicy;
    let href = url;
    const urlParsingNode = policy.urlParsingNode;

    if (!urlParsingNode) {
      return {
        href: url,
        protocol: policy.emptyURL,
        host: policy.emptyURL,
        search: policy.emptyURL,
        hash: policy.emptyURL,
        hostname: policy.emptyURL,
        port: policy.emptyURL,
        pathname: policy.pathSeparator
      };
    }

    if (policy.msie) {
      urlParsingNode.setAttribute('href', href);
      href = urlParsingNode.href;
    }

    urlParsingNode.setAttribute('href', href);

    return {
      href: urlParsingNode.href,
      protocol: urlParsingNode.protocol ? urlParsingNode.protocol.replace(/:$/, '') : '',
      host: urlParsingNode.host,
      search: urlParsingNode.search ? urlParsingNode.search.replace(/^\?/, '') : '',
      hash: urlParsingNode.hash ? urlParsingNode.hash.replace(/^#/, '') : '',
      hostname: urlParsingNode.hostname,
      port: urlParsingNode.port,
      pathname: (urlParsingNode.pathname.charAt(0) === '/') ?
        urlParsingNode.pathname :
        '/' + urlParsingNode.pathname
    };
  }

  isURLSameOrigin(requestURL) {
    const policy = this.urlPolicy;
    if (!policy.hasStandardBrowserEnv) {
      return true;
    }
    const parsed = utils.isString(requestURL) ? this.resolveBrowserURL(requestURL) : requestURL;
    const originURL = policy.originURL;
    if (!originURL || !parsed) {
      return false;
    }
    return parsed.protocol === originURL.protocol && parsed.host === originURL.host;
  }

  encodeQueryValue(val) {
    const policy = this.queryPolicy;
    let encoded = encodeURIComponent(val);
    const replacements = policy.encodeReplacements;
    let i = 0;
    const len = replacements.length;
    while (i < len) {
      const pair = replacements[i++];
      encoded = encoded.replace(pair[0], pair[1]);
    }
    return encoded;
  }

  applyQueryReplacements(encoded) {
    const policy = this.queryPolicy;
    if (!encoded) {
      return encoded;
    }
    let next = encoded;
    for (let i = 0; i < policy.encodeReplacements.length; i++) {
      const pair = policy.encodeReplacements[i];
      next = next.replace(pair[0], pair[1]);
    }
    return next;
  }

  stripHashFragment(url) {
    const policy = this.queryPolicy;
    if (!url) {
      return url;
    }
    const hashmarkIndex = url.indexOf(policy.hashMark);
    if (hashmarkIndex !== -1) {
      return url.slice(0, hashmarkIndex);
    }
    return url;
  }

  appendSerializedParams(url, serializedParams) {
    const policy = this.queryPolicy;
    if (!serializedParams) {
      return url;
    }
    let next = this.stripHashFragment(url);
    next += (next.indexOf(policy.queryDelimiter) === -1 ? policy.queryDelimiter : policy.pairDelimiter) + serializedParams;
    return next;
  }

  serializeParams(params, options, encode) {
    const policy = this.queryPolicy;
    const pairs = [];
    const collector = {
      _pairs: pairs,
      append(name, value) {
        pairs.push([name, value]);
