      url = this.appendSerializedParams(url, serializedParams);
    }

    return url;
  }

  isVisitableValue(thing) {
    const policy = this.queryPolicy;
    if (thing == null && !policy.metaTokens) {
      return false;
    }
    return utils.isPlainObject(thing) || utils.isArray(thing);
  }

